export function TabNav(a,t){return`<div class="memorials-tab-nav" role="tablist">\n    <div class="tab-scroll">${a.map(a=>{const n=a.id===t;return`<button class="memorials-tab-btn ${n?"active":""}" \n        data-tab="${a.id}" \n        role="tab" \n        aria-selected="${n}"\n        tabindex="${n?0:-1}">\n        ${a.label}\n      </button>`}).join("")}</div>\n  </div>`}